70:     this.translate.onLangChange.subscribe((event: LangChangeEvent) => {
71:       this.utilidades.translateFields(this.formTransferencia, 'inscripcion.', 'inscripcion.placeholder_');
72:       this.utilidades.translateFields(this.formReintegro, 'inscripcion.', 'inscripcion.placeholder_');
