99:       ? this.formTransferencia
100:       : this.formReintegro;
101: 
102:     for (let index = 0; index < formulario.campos.length; index++) {
103:       const element = formulario.campos[index];
104:       if (element.nombre === nombre) {
105:         return index
106:       }
107:     }
108:     return 0;
109:   }
