111:   getIndexFormRes(nombre: String): number {
112:     for (let index = 0; index < this.formRespuesta.campos.length; index++) {
113:       const element = this.formRespuesta.campos[index];
114:       if (element.nombre === nombre) {
115:         return index
116:       }
117:     }
118:     return 0;
