123:     if (this.uid !== undefined && this.uid !== 0 && this.uid.toString() !== '' && this.uid.toString() !== '0') {
124:       const persona: any = await this.recuperarPersona(this.uid)
125:       this.nombreCordinador = persona.NombreCompleto;
126:     } else {
127:       this.popUpManager.showAlert(this.translate.instant('GLOBAL.info'), this.translate.instant('GLOBAL.no_info_persona'));
