10: export class ContratoGeneralMidService {
11: 
12:   constructor(private requestManager: RequestManager) {
13:     this.requestManager.setPath('GESTION_CONTRACTUAL_MID_SERVICE');
14:   }
15: 
16:   get(id_contrato: any): Observable<any> {
17:     this.requestManager.setPath('GESTION_CONTRACTUAL_MID_SERVICE');
18:     return this.requestManager.get(`contratos-generales/${id_contrato}`);
19:   }
20: 
21:   postCargaMasivaEspecificaciones(data: any) {
22:     this.requestManager.setPath("GESTION_CONTRACTUAL_MID_SERVICE");
23:     return this.requestManager.post(`cargue-masivo/especificaciones-tecnicas`, data);
