29:   }
30: 
31:   postNumeroContrato(data: any): Observable<any> {
32:     this.requestManager.setPath("GESTION_CONTRACTUAL_MID_SERVICE");
33:     return this.requestManager.post(`contratos-generales/numero-contrato`, data);
34:   }
35: 
36:   getContratos(params: any): Observable<any> {
37:     this.requestManager.setPath('GESTION_CONTRACTUAL_MID_SERVICE');
38:     let queryParams = [];
39:     const filterParams = { ...params };
40:     delete filterParams.limit;
41:     delete filterParams.offset;
42:     delete filterParams.fechaCreacion;
43: 
44:     // Construimos la parte del queryFilter
45:     let queryFilterParts = [];
46: 
47:     // Manejamos los filtros regulares
48:     if (Object.keys(filterParams).length > 0) {
49:       const flatParams = this.flattenObject(filterParams);
50:       queryFilterParts.push(
51:         Object.entries(flatParams)
52:           .map(([key, value]) => `"${key}":${JSON.stringify(value)}`)
53:           .join(',')
54:       );
55:     }
56: 
57:     // Manejamos el filtro de fechas
58:     if (params.fechaCreacion) {
59:       queryFilterParts.push(
60:         `"fechaCreacion":${JSON.stringify(params.fechaCreacion)}`
61:       );
62:     }
63: 
64:     // Si hay algún filtro, lo añadimos a queryParams
65:     if (queryFilterParts.length > 0) {
66:       queryParams.push(
67:         `queryFilter=${encodeURIComponent(queryFilterParts.join(','))}`
68:       );
69:     }
70: 
71:     // Añadimos limit y offset
72:     if (params.limit !== undefined) {
73:       queryParams.push(`limit=${params.limit}`);
74:     }
75:     if (params.offset !== undefined) {
76:       queryParams.push(`offset=${params.offset}`);
77:     }
78: 
79:     const url = `contratos-generales${queryParams.length ? '?' + queryParams.join('&') : ''}`;
80:     return this.requestManager.get(url);
81:   }
82: 
83:   private flattenObject(obj: any, prefix: string = ''): any {
84:     let items: any = {};
85:     for (let key in obj) {
86:       if (obj.hasOwnProperty(key)) {
87:         const newKey = prefix ? `${prefix}.${key}` : key;
88:         if (typeof obj[key] === 'object' && obj[key] !== null) {
89:           Object.assign(items, this.flattenObject(obj[key], newKey));
90:         } else {
91:           items[newKey] = obj[key];
92:         }
93:       }
94:     }
95:     return items;
96:   }
